import logging
import inspect
from .exceptions import UnknownAlias
from .exceptions import AliasAlreadyAssignedError
from .scope import current_scope
from . import logger as core_logger


class AliasRegistry(dict):
    """
    Global registry of all aliases

    Stores different object types under alias key.
    Alias must be unique for all objects (UEs, eNBs, traffics, ...) used inside test case.
    """
    def __init__(self):
        """Initiating alias registry"""
        super(AliasRegistry, self).__init__()
        self.logger = logging.getLogger('al.aliases')

    def __missing__(self, key):
        """
        Accessing nonexisting alias via xxx[alias] raises UnknownAlias

        :param key: alias
        :return: None
        :raises: :py:class:`ta_ue.exceptions.UnknownAlias`: if no such alias in aliases registry
        """
        err_msg = f"alias registry has no '{key}'"
        self.logger.error(f"UnknownAlias({err_msg})")
        raise UnknownAlias(err_msg)

    def __setitem__(self, key, item):
        """
        You can't assign alias to object if given alias is already used

        :param key: alias
        :param item: object to store
        :return: None
        :raises: :py:class:`ta_ue.exceptions.AliasAlreadyAssignedError`: if alias already used for other object
        """
        # Takes code location of caller of this function
        (_, pathname, lineno, func_name, _, _) = inspect.stack(0)[1]
        call_msg = f"set aliases_registry[{key}] to '{item}'  called by {func_name}() [{pathname}:{lineno}]"
        self.logger.debug(call_msg)

        if key in self:
            if item is not self[key]:
                err_msg = f"AliasAlreadyAssignedError({key}, {self[key]}), can't assign to '{item}'"
                self.logger.error(err_msg)
                raise AliasAlreadyAssignedError(key, self[key])
            self.logger.debug(f"alias '{key}' already registered with same value '{item}'")
            return  # to not register same resource twice in scope
        super(AliasRegistry, self).__setitem__(key, item)
        self.logger.debug(f"registered alias '{key}' for value '{item}'")
        current_scope().uses([key], self.release)  # alias is resource we need to release at scope end

    def __getitem__(self, key):
        item = super(AliasRegistry, self).__getitem__(key)
        (_, pathname, lineno, func_name, _, _) = inspect.stack(0)[1]
        if pathname != __file__:  # don't log self[key] called from this file
            call_msg = f"from aliases_registry[{key}] get '{item}'  called by {func_name}() [{pathname}:{lineno}]"
            self.logger.log(level=core_logger.TRACE, msg=call_msg)
        return item

    def release(self, aliases):
        """
        Release unused aliases

        :param aliases: list of aliases to release from registry
        :return: None
        """
        (_, pathname, lineno, func_name, _, _) = inspect.stack(0)[1]
        if pathname == __file__:
            (_, pathname, lineno, func_name, _, _) = inspect.stack(0)[2]
        call_msg = f"aliases_registry.release({aliases})  called by {func_name}() [{pathname}:{lineno}]"
        self.logger.debug(call_msg)
        for alias in aliases:
            if alias in self:
                del self[alias]


__aliases_registry = AliasRegistry()


def aliases_registry():
    """Registry singleton of UEs."""
    return __aliases_registry


def release_aliases(aliases):
    """Release aliases when they are no more used."""
    aliases_registry().release(aliases)
